@page "/shipments"
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Shipment Dashboard</PageTitle>

<h1>Shipment Dashboard</h1>

<button class="btn btn-primary mb-3" @onclick="ShowCreateForm">+ New Shipment</button>

@if (showCreateForm)
{
    <div class="card mb-4 p-3">
        <h4>Create Shipment</h4>
        <div class="row g-2">
            <div class="col-md-3">
                <input @bind="newShipment.Origin" placeholder="Origin" class="form-control" />
            </div>
            <div class="col-md-3">
                <input @bind="newShipment.Destination" placeholder="Destination" class="form-control" />
            </div>
            <div class="col-md-3">
                <input @bind="newShipment.RecipientName" placeholder="Recipient Name" class="form-control" />
            </div>
            <div class="col-md-3">
                <input @bind="newShipment.Description" placeholder="Description" class="form-control" />
            </div>
        </div>
        <div class="row g-2 mt-2">
            <div class="col-md-3">
                <label class="form-label">Estimated Delivery</label>
                <input type="date" @bind="newShipment.EstimatedDelivery" class="form-control" />
            </div>
            <div class="col-md-9 d-flex align-items-end">
                <button class="btn btn-success me-2" @onclick="CreateShipment">Create</button>
                <button class="btn btn-secondary" @onclick="CancelCreate">Cancel</button>
            </div>
        </div>
        @if (!string.IsNullOrEmpty(createError))
        {
            <div class="alert alert-danger mt-2">@createError</div>
        }
    </div>
}

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found. Create one to get started.</p>
}
else
{
    <div class="mb-3">
        <input @bind="filterText" @bind:event="oninput" placeholder="Filter by destination or tracking #..." class="form-control" style="max-width:400px" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Recipient</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><code>@shipment.TrackingNumber</code></td>
                    <td>@shipment.Destination</td>
                    <td>@shipment.RecipientName</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                value="@((int)shipment.Status)"
                                @onchange="(e) => UpdateStatus(shipment, e)">
                            @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@((int)status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private bool showCreateForm;
    private CreateShipmentRequest newShipment = new();
    private string? createError;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(filterText) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate()
    {
        showCreateForm = false;
        newShipment = new();
        createError = null;
    }

    private async Task CreateShipment()
    {
        createError = null;
        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination))
        {
            createError = "Origin and Destination are required.";
            return;
        }

        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            shipments?.Insert(0, created);
            CancelCreate();
        }
        catch (Exception ex)
        {
            createError = $"Failed to create shipment: {ex.Message}";
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusValue))
        {
            var newStatus = (ShipmentStatus)statusValue;
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, new UpdateShipmentStatusRequest { Status = newStatus });
            if (updated is not null)
            {
                shipment.Status = updated.Status;
            }
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown"
                   placeholder="Enter tracking number (e.g., SHP-20260610-12345)"
                   class="form-control" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <strong>Tracking #:</strong> @shipment.TrackingNumber
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>

                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>

                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Recipient</dt>
                        <dd>@shipment.RecipientName</dd>

                        <dt>Shipped On</dt>
                        <dd>@shipment.CreatedAt.ToString("yyyy-MM-dd")</dd>

                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <strong>@shipment.EstimatedDelivery.Value.ToString("yyyy-MM-dd")</strong>
                            }
                            else
                            {
                                <span class="text-muted">Not available</span>
                            }
                        </dd>
                    </dl>
                </div>
            </div>
            @if (!string.IsNullOrEmpty(shipment.Description))
            {
                <p><strong>Description:</strong> @shipment.Description</p>
            }
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private string? errorMessage;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }

    private async Task TrackShipment()
    {
        errorMessage = null;
        shipment = null;

        if (string.IsNullOrWhiteSpace(trackingNumber))
        {
            errorMessage = "Please enter a tracking number.";
            return;
        }

        isLoading = true;
        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            if (shipment is null)
            {
                errorMessage = $"No shipment found with tracking number \"{trackingNumber.Trim()}\".";
            }
        }
        catch
        {
            errorMessage = "An error occurred while looking up the shipment. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

